tool_input.command:
cd src/styles && python - <<'EOF' 2>/dev/null || node -e "
const fs=require('fs');let s=fs.readFileSync('base.css','utf8');
s=s.replace(/@media \(max-width: 1099px\) \{\n  \.plan-grid \{\n    gap: var\(--space-16\);\n  \}\n\}\n/,'');
s=s.replace('width: 128px;','width: calc(var(--size-control-sm) * 4);');
fs.writeFileSync('base.css',s);"
EOF
grep -n "1099\|128px" base.css
